import{_ as n,C as o,o as i,c as a,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"A Reconnected Session Is Not Recovered Work","description":"","frontmatter":{"title":"A Reconnected Session Is Not Recovered Work","date":"2026-08-13","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"What does a successful session rebind establish—and what does it not establish—after the underlying runtime service changes?","summary":"A stable logical session can reopen a failed remote binding while the work already running on the old binding remains interrupted. Generation-scoped identity prevents the replacement host from inheriting stale cell authority, but it does not migrate lost execution.","sources":"research/analysis/Q-20260813-02-session-rebinding-boundary.md","item_id":"Q-20260813-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-13-session-rebinding-execution-continuity-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-08-13-session-rebinding-execution-continuity.md","filePath":"en/industry/2026-08-13-session-rebinding-execution-continuity.md","lastUpdated":1786634417000}'),l={name:"en/industry/2026-08-13-session-rebinding-execution-continuity.md"};function c(d,e,h,u,p,m){const t=o("ArticleCover");return i(),a("div",null,[r(t,{image:"/assets/covers/daily-2026-08-13-session-rebinding-execution-continuity-cover.png",kicker:"Industry Architecture · Daily Research",title:"A Reconnected Session Is Not Recovered Work",summary:"A stable logical session can reopen a failed remote binding while the work already running on the old binding remains interrupted. Generation-scoped identity prevents the replacement host from inheriting stale cell authority, but it does not migrate lost execution.",version:"Q-20260813-02",status:"Daily Runtime V5 · 2026-08-13",languageHref:"/zh/industry/2026-08-13-session-rebinding-execution-continuity",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="a-reconnected-session-is-not-recovered-work" tabindex="-1">A Reconnected Session Is Not Recovered Work <a class="header-anchor" href="#a-reconnected-session-is-not-recovered-work" aria-label="Permalink to &quot;A Reconnected Session Is Not Recovered Work&quot;">​</a></h1><p>When a remote runtime disappears and a client reconnects, the most tempting status message is also the most misleading: “the session recovered.” That phrase can describe at least two different outcomes. The logical session may be usable again for future operations, while work already executing on the failed binding has ended and will never continue.</p><p>The selected Codex gRPC code-mode change makes this distinction concrete. It keeps a stable public session object, replaces a stopped remote binding on demand, serializes concurrent attempts to open the replacement, and gives each binding a generation. The implementation restores later availability without claiming that old in-flight work migrated.</p><p>That boundary matters far beyond one transport. Any system that preserves a stable user-facing identity over replaceable workers, hosts or connections needs to say whether it recovered the <strong>control surface</strong>, the <strong>execution</strong>, the <strong>result</strong>, or only the ability to start new work.</p><h2 id="a-stable-session-can-outlive-a-failed-binding" tabindex="-1">A stable session can outlive a failed binding <a class="header-anchor" href="#a-stable-session-can-outlive-a-failed-binding" aria-label="Permalink to &quot;A stable session can outlive a failed binding&quot;">​</a></h2><p>The public session in the examined implementation is not identical to one remote host session. It owns a replaceable binding. Before <code>execute</code>, <code>wait</code> or <code>terminate</code>, the client checks whether the current binding remains live. If it has stopped, the client may open a replacement binding to the same service endpoint.</p><p>This is a useful availability property: callers can retain the logical session instead of rebuilding every reference in the application. But the stable outer identity should not erase the lifecycle of the resource underneath it. The old binding and the new binding are different execution epochs.</p><p>A one-permit semaphore makes reopening single-flight. The first caller that observes the failure acquires the permit and opens the replacement. A later concurrent caller rechecks after acquiring the permit and reuses the already-published binding. The lock controls replacement creation; it does not globally serialize the cells that run after the replacement becomes available.</p><p>The source-backed evidence is the same-day Research Object, based on <a href="https://github.com/openai/codex/commit/bde723ae7dedc87754228a2476a7a4cfbf05b4b8" target="_blank" rel="noreferrer">OpenAI Codex commit <code>bde723a</code></a> and <a href="https://github.com/openai/codex/pull/38257" target="_blank" rel="noreferrer">PR #38257</a>. These are public primary-source implementation records, not independent validation of a general recovery architecture.</p><h2 id="generation-identity-draws-the-epoch-boundary" tabindex="-1">Generation identity draws the epoch boundary <a class="header-anchor" href="#generation-identity-draws-the-epoch-boundary" aria-label="Permalink to &quot;Generation identity draws the epoch boundary&quot;">​</a></h2><p>Reopening alone creates an identity problem. A replacement host may restart its local cell counter at <code>1</code>. If the public API exposes only that host-local number, an old reference to cell <code>1</code> can be mistaken for the replacement host&#39;s new cell <code>1</code>.</p><p>The selected design prevents that aliasing by assigning a generation to each binding. Generation one keeps the original public form; later bindings expose identifiers such as <code>g2:1</code>. The same mapping is applied to nested tool calls, notifications and cell-closed callbacks, so callback ownership follows the binding epoch instead of merely matching a recycled local number.</p><p><code>wait</code> and <code>terminate</code> translate a public cell ID only when its generation matches the live binding. A stale generation is rejected rather than forwarded to the replacement host. This rejection is not a recovery failure. It is the mechanism that prevents a stale caller from controlling unrelated new work.</p><p>Generation identity therefore answers a narrow but important question: <strong>which live binding epoch owns this reference?</strong> It does not answer whether the old cell can be reconstructed, whether its side effects committed, or whether a result was lost.</p><h2 id="rebinding-restores-future-availability-not-past-execution" tabindex="-1">Rebinding restores future availability, not past execution <a class="header-anchor" href="#rebinding-restores-future-availability-not-past-execution" aria-label="Permalink to &quot;Rebinding restores future availability, not past execution&quot;">​</a></h2><p>The integration test preserves the distinction instead of hiding it. The original host session is interrupted; the pending old wait ends and the old cell closes. A replacement host starts at the same endpoint. Two later executions complete under generation-two identities, while operations against the old generation are rejected.</p><p>This supports a bounded conclusion:</p><ul><li>the logical session remains useful after host replacement;</li><li>replacement creation is coordinated;</li><li>old and new cell identities are not confused;</li><li>new work can run concurrently after the rebind;</li><li>work already executing on the old host is interrupted rather than migrated.</li></ul><p>Calling all of this “session recovery” without qualifiers would upgrade later availability into an unsupported execution-continuity claim. A clearer operational vocabulary would report at least <code>Rebound</code>, <code>Old Work Interrupted</code>, <code>New Work Admitted</code>, and—only when separately established—<code>Work Reconstructed</code> or <code>Result Recovered</code>.</p><h2 id="recovery-needs-more-than-one-status" tabindex="-1">Recovery needs more than one status <a class="header-anchor" href="#recovery-needs-more-than-one-status" aria-label="Permalink to &quot;Recovery needs more than one status&quot;">​</a></h2><p>A remote-session control plane should record the outcomes that operators actually need to distinguish.</p><p><strong>Logical identity.</strong> Does the caller still address the same public session?</p><p><strong>Binding epoch.</strong> Which live connection or host generation currently implements that session?</p><p><strong>Execution continuity.</strong> Did an in-flight operation continue, restart, fail, or become unknown?</p><p><strong>Result continuity.</strong> Is there durable evidence for the old operation&#39;s terminal result?</p><p><strong>Admission.</strong> May a later operation start on the replacement binding?</p><p>These dimensions should not collapse into a single green badge. A stable session with a new binding and an unknown prior side effect is operationally very different from a session whose work was durably replayed and reconciled.</p><p>The same separation improves automation. A retry policy can admit new work after <code>Rebound</code> while holding any non-idempotent old operation for reconciliation. Telemetry can count host replacements separately from reconstructed work. User interfaces can explain that the workspace is available again without claiming that the interrupted command completed.</p><h2 id="what-remains-unrecovered" tabindex="-1">What remains unrecovered <a class="header-anchor" href="#what-remains-unrecovered" aria-label="Permalink to &quot;What remains unrecovered&quot;">​</a></h2><p>The implementation keeps generation state in the client process. The examined source does not establish durable generation identity across a client restart. It also does not recover results lost with the previous runtime service, prove bounded retry under repeated instability, or define a general transport-independent session protocol.</p><p>Globally unique remote resource identifiers could avoid local-number aliasing through another mechanism. A system with durable operation journals could reconstruct selected work after replacement. Those alternatives do not weaken the main judgment: whatever mechanism is chosen, rebinding and work recovery must remain separately observable.</p><p>The evidence supports an architectural discipline, not a universal implementation prescription. A replacement binding restores a path for future operations. It does not, by itself, carry old execution across the gap.</p><h2 id="questions-for-a-durable-design" tabindex="-1">Questions for a durable design <a class="header-anchor" href="#questions-for-a-durable-design" aria-label="Permalink to &quot;Questions for a durable design&quot;">​</a></h2><p>Three design questions remain open.</p><ol><li>When must a binding generation become durable rather than process-local?</li><li>Which interrupted work classes may be reconstructed safely, and which require explicit reconciliation or human review?</li><li>How should the system report an operation whose remote host disappeared after a possible side effect but before a durable result?</li></ol><p>Until those questions are answered, “reconnected” should stay exactly that: evidence that a new binding exists, not proof that the old work survived.</p><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><ul><li><a href="https://github.com/openai/codex/commit/bde723ae7dedc87754228a2476a7a4cfbf05b4b8" target="_blank" rel="noreferrer">OpenAI Codex commit <code>bde723ae</code>: generation-aware gRPC session recovery</a></li><li><a href="https://github.com/openai/codex/pull/38257" target="_blank" rel="noreferrer">OpenAI Codex PR #38257</a></li><li><code>research/reading/Q-20260813-02-generation-aware-grpc-session-recovery.md</code></li><li><code>research/analysis/Q-20260813-02-session-rebinding-boundary.md</code></li></ul>',38))])}const f=n(l,[["render",c]]);export{g as __pageData,f as default};
